def _guards() -> None:
    op.execute("""
    CREATE FUNCTION pdf_source_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Immutable source' USING ERRCODE='23514'; END IF;
      IF TG_OP='INSERT' THEN
        IF NEW.material_id IS NOT NULL THEN
          RAISE EXCEPTION 'Source must start unbound' USING ERRCODE='23514'; END IF;
      ELSE
        IF OLD.archived_at IS NOT NULL OR
          (OLD.material_id IS NOT NULL AND NEW.material_id IS DISTINCT FROM OLD.material_id) OR
          (to_jsonb(OLD)-ARRAY['material_id','updated_at','row_version','archived_at']) IS
          DISTINCT FROM
          (to_jsonb(NEW)-ARRAY['material_id','updated_at','row_version','archived_at']) THEN
          RAISE EXCEPTION 'Immutable source' USING ERRCODE='23514'; END IF;
      END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER pdf_source_guard BEFORE INSERT OR UPDATE OR DELETE ON reading_material_sources
      FOR EACH ROW EXECUTE FUNCTION pdf_source_guard();

    CREATE FUNCTION pdf_source_binding() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE s reading_material_sources%ROWTYPE;
    BEGIN
      SELECT * INTO STRICT s FROM reading_material_sources WHERE id=NEW.id;
      IF s.material_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reading_materials m JOIN reading_material_revisions v ON v.material_id=m.id
        JOIN reading_material_extraction_runs r ON r.id=v.extraction_run_id
        WHERE m.id=s.material_id AND m.learner_id=s.learner_id AND r.source_id=s.id
          AND r.status='extracted'
      ) THEN RAISE EXCEPTION 'Invalid source binding' USING ERRCODE='23514'; END IF;
      RETURN NULL;
    END $$;
    CREATE CONSTRAINT TRIGGER pdf_source_binding AFTER INSERT OR UPDATE ON reading_material_sources
      DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pdf_source_binding();

    CREATE FUNCTION pdf_run_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Immutable extraction' USING ERRCODE='23514'; END IF;
      IF TG_OP='INSERT' THEN
        IF NEW.status <> 'running' THEN
          RAISE EXCEPTION 'Attempt must begin running' USING ERRCODE='23514'; END IF;
      ELSE
        IF OLD.status <> 'running' OR
          (to_jsonb(OLD)-ARRAY['status','finished_at','row_version','outcome_code','assembled_text',
          'assembled_text_sha256','total_page_count','pages_with_lexical_text',
          'pages_with_zero_characters','pages_with_zero_lexical_words','extracted_character_count',
          'assembled_character_count','lexical_word_count']) IS DISTINCT FROM
          (to_jsonb(NEW)-ARRAY['status','finished_at','row_version','outcome_code','assembled_text',
          'assembled_text_sha256','total_page_count','pages_with_lexical_text',
          'pages_with_zero_characters','pages_with_zero_lexical_words','extracted_character_count',
          'assembled_character_count','lexical_word_count']) THEN
          RAISE EXCEPTION 'Immutable extraction' USING ERRCODE='23514'; END IF;
        IF NEW.status IN ('extracted','ocr_required','needs_review') AND
          (clock_timestamp() >= NEW.lease_expires_at OR NEW.finished_at >=
          NEW.lease_expires_at) THEN
          RAISE EXCEPTION 'Expired extraction' USING ERRCODE='23514'; END IF;
      END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER pdf_run_guard BEFORE INSERT OR UPDATE OR DELETE
      ON reading_material_extraction_runs FOR EACH ROW EXECUTE FUNCTION pdf_run_guard();

    CREATE FUNCTION pdf_page_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE state text;
    BEGIN
      IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Immutable page' USING ERRCODE='23514'; END IF;
      SELECT status INTO state FROM reading_material_extraction_runs
        WHERE id=NEW.extraction_run_id FOR UPDATE;
      IF state IS DISTINCT FROM 'running' THEN
        RAISE EXCEPTION 'Invalid page parent' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER pdf_page_guard BEFORE INSERT OR UPDATE OR DELETE
      ON reading_material_extraction_pages FOR EACH ROW EXECUTE FUNCTION pdf_page_guard();

    CREATE FUNCTION pdf_consistency() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE r reading_material_extraction_runs%ROWTYPE; n bigint; chars bigint; words bigint;
      lexical bigint; empty_pages bigint; wordless bigint;
    BEGIN
      SELECT * INTO STRICT r FROM reading_material_extraction_runs WHERE id=NEW.id;
      SELECT count(*),sum(raw_character_count),sum(lexical_word_count),
        count(*) FILTER (WHERE lexical_word_count>0),
        count(*) FILTER (WHERE raw_character_count=0),
        count(*) FILTER (WHERE lexical_word_count=0)
      INTO n,chars,words,lexical,empty_pages,wordless
      FROM reading_material_extraction_pages WHERE extraction_run_id=r.id;
      IF r.status IN ('running','failed') THEN
        IF n<>0 THEN
          RAISE EXCEPTION 'Unpublished pages' USING ERRCODE='23514'; END IF;
      ELSE
        IF n<>r.total_page_count OR chars<>r.extracted_character_count
          OR words<>r.lexical_word_count
          OR lexical<>r.pages_with_lexical_text OR empty_pages<>r.pages_with_zero_characters
          OR wordless<>r.pages_with_zero_lexical_words THEN
          RAISE EXCEPTION 'Inconsistent extraction counts' USING ERRCODE='23514'; END IF;
        IF EXISTS (SELECT 1 FROM (
          SELECT *,row_number() OVER (ORDER BY page_number) AS expected,
            lag(text_end+2,1,0) OVER (ORDER BY page_number) AS expected_start
          FROM reading_material_extraction_pages WHERE extraction_run_id=r.id
        ) p WHERE p.page_number<>expected OR p.text_start<>expected_start
          OR p.text_end>r.assembled_character_count
          OR (p.page_number=r.total_page_count AND p.text_end<>r.assembled_character_count)
          OR (p.page_number<r.total_page_count AND substring(r.assembled_text FROM
          p.text_end+1 FOR 2)<>E'\n\n')
        ) THEN RAISE EXCEPTION 'Inconsistent page spans' USING ERRCODE='23514'; END IF;
        IF r.status='extracted' AND EXISTS (SELECT 1 FROM reading_material_extraction_pages
          WHERE extraction_run_id=r.id AND cardinality(warning_codes)>0) THEN
          RAISE EXCEPTION 'Unresolved warnings' USING ERRCODE='23514'; END IF;
        IF r.status='ocr_required' AND NOT EXISTS (SELECT 1 FROM reading_material_extraction_pages
          WHERE extraction_run_id=r.id AND lexical_word_count=0 AND
          'painted_image'=ANY(warning_codes)) THEN
          RAISE EXCEPTION 'Missing image evidence' USING ERRCODE='23514'; END IF;
        IF r.status='needs_review' AND NOT EXISTS (SELECT 1 FROM reading_material_extraction_pages
          WHERE extraction_run_id=r.id AND cardinality(warning_codes)>0) THEN
          RAISE EXCEPTION 'Missing review evidence' USING ERRCODE='23514'; END IF;
      END IF;
      IF (r.status='extracted') IS DISTINCT FROM EXISTS (
        SELECT 1 FROM reading_material_revisions WHERE extraction_run_id=r.id
      ) THEN RAISE EXCEPTION 'Invalid revision publication' USING ERRCODE='23514'; END IF;
      RETURN NULL;
    END $$;
    CREATE CONSTRAINT TRIGGER pdf_consistency AFTER INSERT OR UPDATE
      ON reading_material_extraction_runs DEFERRABLE INITIALLY DEFERRED
      FOR EACH ROW EXECUTE FUNCTION pdf_consistency();

    CREATE FUNCTION pdf_page_state() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NOT EXISTS (SELECT 1 FROM reading_material_extraction_runs WHERE id=NEW.extraction_run_id
        AND status IN ('extracted','ocr_required','needs_review')) THEN
        RAISE EXCEPTION 'Unpublished page' USING ERRCODE='23514'; END IF;
      RETURN NULL;
    END $$;
    CREATE CONSTRAINT TRIGGER pdf_page_state AFTER INSERT ON reading_material_extraction_pages
      DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pdf_page_state();

    CREATE FUNCTION pdf_revision_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF NEW.extraction_run_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM reading_material_extraction_runs r
        JOIN reading_material_sources s ON s.id=r.source_id
        JOIN reading_materials m ON m.id=s.material_id
        WHERE r.id=NEW.extraction_run_id AND r.status='extracted' AND m.id=NEW.material_id
          AND m.learner_id=s.learner_id AND NEW.original_text=r.assembled_text
          AND NEW.source_sha256=r.assembled_text_sha256
          AND NEW.language_tag=s.language_tag AND NEW.title=s.title
      ) THEN RAISE EXCEPTION 'Invalid revision extraction evidence' USING ERRCODE='23514'; END IF;
      RETURN NULL;
    END $$;
    CREATE CONSTRAINT TRIGGER pdf_revision_evidence AFTER INSERT ON reading_material_revisions
      DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION pdf_revision_evidence();
    """)
